"""Shared publishing for explicitly authored requirement maps (no coverage inference)."""
from pathlib import Path
import csv,json,html
R=Path(__file__).resolve().parent.parent
def publish(unit,source,pages,rows,bridges):
 P=R/f'practical-packs/unit{unit}-evidence';P.mkdir(parents=True,exist_ok=True);H=html.escape
 for key,b in bridges.items():
  table=''.join(f'<tr><th scope="row">{H(label)}</th><td>{H(text)}</td></tr>' for label,text in b['models'])
  body=f'<p>Unit {unit} · fictional bicycle-shop client brief. Read <a href="../../index.html#topic/{b["chapter"]}/{b["section"]}">the chapter explanation</a> first. These are worked decisions, not observed learner results.</p><section id="worked"><h2>Worked decisions</h2><div class="table-scroll" tabindex="0" role="region" aria-label="Worked example"><table><thead><tr><th>Focus</th><th>Decision and explanation</th></tr></thead><tbody>{table}</tbody></table></div>{b.get("extra", "")}</section><section id="independent"><h2>Apply independently</h2><p>{H(b["task"])}</p><p>Use this within the existing chapter task, not an extra assessed project or additional teaching week. Record expected and actual results separately.</p></section><section id="checks"><h2>Evidence to retain</h2><ul>'+''.join('<li>'+H(c)+'</li>' for c in b['checks'])+'</ul><p>Actual learner performance, native application output and independent teacher review remain unverified. Supplied model results must not be copied into an observed-result log.</p></section>'
  (P/f'{key}.html').write_text(f'<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{H(b["title"])} · Unit {unit} AIT</title><link rel="stylesheet" href="../style.css"><style>.table-scroll{{overflow:auto}}@media print{{nav{{display:none}}}}</style></head><body><main><nav><a href="../../index.html#contents">Textbook contents</a> · <a href="index.html">Unit {unit} worked evidence</a> · <a href="../../audits/unit{unit}-reconciliation.html">Requirement map</a></nav><h1>{H(b["title"])}</h1>{body}</main></body></html>',encoding='utf-8')
 nav=''.join(f'<li><a href="{key}.html">{H(b["title"])}</a></li>' for key,b in bridges.items())
 (P/'index.html').write_text(f'<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Unit {unit} worked evidence · AIT ATAR</title><link rel="stylesheet" href="../style.css"></head><body><main><nav><a href="../../index.html#contents">Textbook contents</a> · <a href="../index.html">Practical library</a></nav><h1>Unit {unit}: worked evidence and independent application</h1><p>Targeted support for the existing chapter tasks and individual syllabus requirements. No extra teaching or exam weeks are added.</p><ul>{nav}</ul><p><a href="../../audits/unit{unit}-reconciliation.html">Requirement map</a> · <a href="../unit{unit}-evidence-v1.zip" download>Download this pack</a></p></main></body></html>',encoding='utf-8')
 for r in rows:
  r['source_url']=source+'#page='+str(r['page']+4)
  r['explanation_url']='https://edugenio.github.io/ait-atar-textbook/index.html'+r['explanation'].split('index.html')[1]
  r['worked_url']=f'https://edugenio.github.io/ait-atar-textbook/practical-packs/unit{unit}-evidence/'+r['worked']
  r['practice_url']=f'https://edugenio.github.io/ait-atar-textbook/practical-packs/unit{unit}-evidence/'+r['practice']
 out=R/'audits';data={'review_date':'2026-10-27','source':source,'version':'2013/35758[v5], effective 2026','scope':f'Unit {unit} content only, printed pp. {pages}','numbering':'Local source-order locators, not official SCSA codes. Parents are context rows; leaf counts are not completion percentages.','requirements':rows}
 (out/f'unit{unit}-requirements.json').write_text(json.dumps(data,indent=2)+'\n',encoding='utf-8')
 with (out/f'unit{unit}-requirements.csv').open('w',newline='',encoding='utf-8-sig') as f:
  writer=csv.DictWriter(f,fieldnames=list(rows[0]));writer.writeheader();writer.writerows(rows)
 table=''.join(f'<tr id="{r["id"]}"><th scope="row">{r["id"]}</th><td>{H(r["summary"])}<br><small>p. {r["page"]} · {H(r["locator"])}</small></td><td><a href="{r["explanation"].replace("../../index.html","../index.html")}">Explanation</a> · <a href="../practical-packs/unit{unit}-evidence/{r["worked"]}">Worked model</a> · <a href="../practical-packs/unit{unit}-evidence/{r["practice"]}">Independent task</a></td><td>{H(r["status"])}<p>{H(r["limitation"])}</p></td></tr>' for r in rows)
 leaves=sum(not r['context'] for r in rows)
 (out/f'unit{unit}-reconciliation.html').write_text(f'<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Unit {unit} individual requirement reconciliation · AIT ATAR</title><link rel="stylesheet" href="../practical-packs/style.css"></head><body><main><nav><a href="../index.html#contents">Textbook contents</a> · <a href="../index.html#audits">Audit hub</a> · <a href="../practical-packs/index.html">Practical library</a></nav><h1>Unit {unit} individual requirement reconciliation</h1><p>27 October 2026 · Year 11 from 2026 · <a href="{source}">Official SCSA syllabus</a>, printed pp. {pages}.</p><p>{len(rows)} source-order rows: {leaves} leaf reviews and {len(rows)-leaves} parent contexts. Local IDs describe order, not official SCSA codes or a completion percentage. A task being authored does not demonstrate learner performance or independent approval.</p><p><a href="unit{unit}-requirements.csv" download>Download CSV</a> · <a href="unit{unit}-requirements.json" download>Structured hierarchy</a> · <a href="../practical-packs/unit{unit}-evidence/index.html">Student worked evidence</a></p><div class="table-scroll" style="overflow:auto" tabindex="0" role="region" aria-label="Unit {unit} requirement map"><table><thead><tr><th>Local ID</th><th>Requirement / source locator</th><th>Teaching evidence</th><th>Status / remaining check</th></tr></thead><tbody>{table}</tbody></table></div></main></body></html>',encoding='utf-8')
 print(f'Unit {unit}: {len(rows)} source-order rows, {leaves} leaf rows, {len(bridges)} teaching bridges.')
